-- 自包含单测试文件（开启内置字符串加密）
-- 在 andlua 中直接运行

local function run_test(name, encoded)
  io.write("[TEST] " .. name .. " ... ")
  local ok, data = pcall(string.dec, encoded)
  if not ok then print("DEC_FAIL: " .. tostring(data)); return end
  local ok2, func = pcall(load, data)
  if not ok2 then print("LOAD_FAIL: " .. tostring(func)); return end
  local old_print = print; local outputs = {}
  print = function(...) local p={} for i=1,select('#',...) do p[i]=tostring(select(i,...)) end table.insert(outputs,table.concat(p,'\t')) end
  local ok3, err = pcall(func); print = old_print
  if not ok3 then print("RUN_FAIL: " .. tostring(err))
  else print("PASS (" .. #outputs .. " lines)") end
end

print("=== 单测试开始 (内置加密开启) ===")
print("时间: " .. os.date())

run_test("original", "")

run_test("str_encrypt_xor", "")

run_test("str_split_pure_insn", "")

run_test("num_obfuscate", "")

run_test("bool_obfuscate", "")

run_test("full_all_modules", "")

print("=== 测试结束 ===")